/* PLAYER · Icon-System — die einzige Quelle. Kein zweites Icon irgendwo.

   Diese Datei ist NICHT von Hand gezeichnet. Die Pfade stammen 1:1 aus
   Olivers Icon-Blatt (Affinity-EPS vom 23.09.2026); ein Skript hat die
   PostScript-Kurven ausgelesen, die y-Achse gespiegelt und jedes Motiv in
   ein 24×24-Raster gerechnet. Deshalb sitzt hier kein Naeherungswert,
   sondern exakt die gezeichnete Form — inklusive der leicht unruhigen
   Marker-Kontur, die den Charakter ausmacht.

   Bauweise:
     · 24×24-Raster, jedes Motiv auf 20 Einheiten normiert und zentriert
     · GEFUELLTE Formen (fill), keine Striche. Das Blatt ist so gezeichnet:
       die Kontur ist Teil der Zeichnung, nicht ein stroke-Wert.
     · Farbe IMMER aus currentColor — nie im Icon gesetzt
     · fillRule "evenodd", damit Loecher (Kreise, Pokalschale) offen bleiben

   Farbregel (siehe app/globals.css):
     auf hell   → #111111, sparsam #078A3B
     auf dunkel → weiss, sparsam #39FF14

   Wird das Blatt neu gezeichnet, wird diese Datei neu erzeugt — nicht von
   Hand nachgebessert.

   Ohne "use client" — laeuft in Server- wie Client-Seiten. */

type IconProps = {
  size?: number
  /** Gesetzt = das Icon traegt Bedeutung und bekommt einen Namen. */
  titel?: string
  style?: React.CSSProperties
}

function Rahmen({ size = 24, titel, style, children }: IconProps & { children: React.ReactNode }) {
  return (
    <svg
      width={size} height={size} viewBox="0 0 24 24"
      fill="currentColor" fillRule="evenodd" clipRule="evenodd"
      role={titel ? "img" : undefined}
      aria-hidden={titel ? undefined : true}
      aria-label={titel}
      style={{ flexShrink: 0, display: "block", ...style }}
    >
      {children}
    </svg>
  )
}


