/* ── Die beiden Pfeile stehen NICHT auf Olivers Blatt. Sie sind reine
   Bedienzeichen und deshalb bewusst nuechtern gestrichelt statt im
   Marker-Stil — sonst wuerde jede Listenzeile mitzeichnen. ── */
function Strich({ size, titel, style, children }: IconProps & { children: React.ReactNode }) {
  return (
    <svg
      width={size} height={size} viewBox="0 0 24 24"
      fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round"
      role={titel ? "img" : undefined} aria-hidden={titel ? undefined : true} aria-label={titel}
      style={{ flexShrink: 0, display: "block", ...style }}
    >{children}</svg>
  )
}

/** Weiterfuehrender Pfeil — sitzt in Links wie "Alle →". */
export function IconPfeil({ size = 18, ...p }: IconProps) {
  return <Strich size={size} {...p}><path d="M3.2 12h16.2M12.8 5.4 19.4 12l-6.6 6.6" /></Strich>
}

/** Zeilen-Pfeil rechts in einer Liste. */
export function IconChevron({ size = 19, ...p }: IconProps) {
  return <Strich size={size} {...p}><path d="M9 5.4 15.6 12 9 18.6" /></Strich>
}
